export type ConfigName = 
    'DisallowTextPreview' |
    'DisallowMediaPreview' |
    'DisallowAudioPreview' |
    'DisallowVideoPreview' |
    'DisallowImagePreview' |
    'DisallowOnlinePreview' |
    'DisallowPdfPreview' |
    'DisallowOnlineOfficeFilePreview' |
    'PreferredVolume';

export interface ConfigProvider {
    get(name: ConfigName): Promise<string | null>;
    set(name: ConfigName, value: string): Promise<void>;
}
let configProvider: ConfigProvider;
const createDefaultConfigProvider = (): ConfigProvider => {
    const storage = new Map<ConfigName, string>();
    return {
        async get(name) {
            return storage.get(name) || null;
        },
        async set(name, value) {
            storage.set(name, value);
        }
    };
};
configProvider = createDefaultConfigProvider();
export const setConfigProvider = (provider: ConfigProvider) => { configProvider = provider; }
export async function config(name: ConfigName, value: string) { return await configProvider.set(name, value); }

